import itertools
import pysat
from pysat.solvers import Glucose3

def check_graph(edges, n=12):
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = adj[v][u] = True

    # Check independence number <= 3
    for subset in itertools.combinations(range(n), 4):
        independent = True
        for i, u in enumerate(subset):
            for v in subset[i+1:]:
                if adj[u][v]:
                    independent = False
                    break
            if not independent:
                break
        if independent:
            return False, "alpha >= 4"

    # Check vertex connectivity >= 4
    for size in range(0, 4):
        for S in itertools.combinations(range(n), size):
            remaining = [v for v in range(n) if v not in S]
            if not remaining:
                continue
            visited = {remaining[0]}
            queue = [remaining[0]]
            while queue:
                u = queue.pop()
                for v in remaining:
                    if v not in visited and adj[u][v]:
                        visited.add(v)
                        queue.append(v)
            if len(visited) != len(remaining):
                return False, f"kappa <= {size}, S={S}"

    return True, "OK"

n = 12
vars = {}
counter = 1
for i in range(n):
    for j in range(i+1, n):
        vars[(i,j)] = counter
        counter += 1

g = Glucose3()

# For each 4-set, at least one edge
for subset in itertools.combinations(range(n), 4):
    clause = [vars[(u,v)] for u,v in itertools.combinations(subset, 2)]
    g.add_clause(clause)

print("Solving...")
result = g.solve()
print("Result:", result)
if result:
    model = g.get_model()
    edges = []
    for (i,j), var in vars.items():
        if model[var-1] > 0:
            edges.append((i,j))
    print("Edges:", edges)
    print("Number of edges:", len(edges))
    ok, msg = check_graph(edges)
    print("Check:", ok, msg)
else:
    print("No solution")
